        let package_ids = package
            .canonical_manifests()
            .map(|manifest| {
                ReleasePackageId::new(manifest.ecosystem(), package.id.name())
                    .map_err(|_error| GraphError::ReleaseIntentStale)
            })
            .collect::<Result<Vec<_>, _>>()?;
