                    entries.push(ReleaseDecisionEntry { package: id, target_version: after, reasons: vec![ReleaseInclusionReason::Changeset] });
                } else if changed_version {
                    return Err(GraphError::ReleaseIntentStale);
                }
            }
        }
        if observed != selected { return Err(GraphError::ReleaseIntentStale); }
        ReleaseDecisionV1::new(entries).map_err(|_error| GraphError::ReleaseIntentStale)
    }
