12	/// Writes the dry-run text notice for the publish command to the given
13	/// writer. When the plan contains no publishable packages, emits a clear
14	/// "nothing to publish (dry run)" message; otherwise previews the plan.
15	pub(crate) fn write_dry_run_text<W: std::io::Write>(
16	    plan: &callisto_model::PublishPlan,
17	    w: &mut W,
18	) -> std::io::Result<()> {
19	    let is_empty = plan.rust_crates.is_empty()
20	        && plan.npm_main_packages.is_empty()
21	        && plan.npm_platform_packages.is_empty()
22	        && plan.pypi_packages.is_empty()
23	        && plan.releases.is_empty();
24	    if is_empty {
25	        writeln!(w, "Nothing to publish (dry run).")?;
26	    } else {
27	        writeln!(
28	            w,
29	            "Dry run: about to publish the following plan (nothing will be published):"
30	        )?;
31	        render::render_publish(plan, w)?;
32	    }
33	    Ok(())
34	}
