36	/// Checks whether the environment has credentials for each ecosystem in
37	/// the plan. Returns human-readable warnings for any missing credentials
38	/// so the operator can spot auth problems before publishing; empty when
39	/// all required credentials are present.
40	///
41	/// `env` is injectable (pass [`std::env::var`] in production; a closure
42	/// in tests to avoid mutating the process environment).
43	///
44	/// Soft pre-flight check only -- doesn't fail hard. Missing credentials
45	/// may still let publish succeed via an alternative auth mechanism (a
46	/// pre-configured `.npmrc` or `~/.cargo/credentials`).
47	#[cfg(test)]
48	fn check_credentials(
49	    plan: &callisto_model::PublishPlan,
50	    env: impl Fn(&str) -> Result<String, std::env::VarError>,
51	) -> Vec<String> {
52	    let mut warnings = Vec::new();
53	
54	    // Cargo: crates targeting the default crates.io registry need
55	    // CARGO_REGISTRY_TOKEN; crates targeting a named private registry need
56	    // CARGO_REGISTRIES_<UPPERCASE_NAME>_TOKEN. Collect the distinct variable
57	    // names required and warn once per missing variable.
58	    let mut cargo_vars_checked = std::collections::BTreeSet::new();
59	    for pkg in &plan.rust_crates {
60	        let var = match &pkg.registry {
61	            None => "CARGO_REGISTRY_TOKEN".to_string(),
62	            Some(name) => format!("CARGO_REGISTRIES_{}_TOKEN", name.to_uppercase().replace('-', "_")),
63	        };
64	        if cargo_vars_checked.insert(var.clone()) && env(&var).is_err() {
65	            warnings.push(format!(
66	                "warning: {var} is not set; cargo publish may fail authentication"
67	            ));
68	        }
69	    }
70	
71	    if (!plan.npm_main_packages.is_empty() || !plan.npm_platform_packages.is_empty()) && env("NPM_TOKEN").is_err() {
72	        warnings.push("warning: NPM_TOKEN is not set; npm publish may fail authentication".to_string());
73	    }
74	
75	    if !plan.pypi_packages.is_empty() && env("TWINE_PASSWORD").is_err() {
76	        warnings.push("warning: TWINE_PASSWORD is not set; twine upload may fail authentication".to_string());
77	    }
78	
79	    warnings
80	}
