13	pub fn create_tags<R: CommandRunner, D: DependencyResolver>(
14	    ws: &Workspace<'_, R, D>,
15	    plan: &PublishPlan,
16	    permit: Option<&ApplyPermit>,
17	) -> Result<TagReport, GraphError> {
18	    create_tags_with_options(ws, plan, &TagOptions::default(), permit)
19	}
