21	/// Creates one git tag per release in `plan`.
22	///
23	/// `permit` is the dry-run gate: `None` reports the tags that *would* be
24	/// created without touching a single ref, `Some` creates them. It replaces the
25	/// former `TagOptions::dry_run` bool so that the preview branch and the write
26	/// branch cannot disagree -- the write calls simply do not typecheck without a
27	/// permit in hand.
28	pub fn create_tags_with_options<R: CommandRunner, D: DependencyResolver>(
29	    ws: &Workspace<'_, R, D>,
30	    plan: &PublishPlan,
31	    opts: &TagOptions,
32	    permit: Option<&ApplyPermit>,
33	) -> Result<TagReport, GraphError> {
34	    let mut tags = Vec::new();
35	
36	    // `Workspace::git_access` never hard-fails on a missing gix discovery:
37	    // `wasm32` has no gix at all (excluded from that target's dependency
38	    // set), and even natively a failed discovery just means every op below
39	    // runs through the `CommandRunner` fallback instead. Its write
40	    // operations (`create_tag`/`create_floating_major`) additionally
41	    // guarantee a discovered repo's result is authoritative and never
42	    // masked by a shell retry -- see `GitAccess`'s doc comment. Sharing the
43	    // workspace-scoped instance (rather than a fresh `GitAccess::discover`)
44	    // means this command doesn't pay for a second discovery when `ws.tags()`
45	    // below also needs one.
46	    let git = ws.git_access();
47	
48	    for release in &plan.releases {
49	        let tag_str = release.tag_name.as_str();
50	
51	        let Some(permit) = permit else {
52	            if opts.floating_major {
53	                let tmpl = ws.tags()?.template(&release.package);
54	                if let Some(v_str) = tmpl.extract_version_str(release.tag_name.as_str()) {
55	                    let grammar = ws
56	                        .graph
57	                        .packages()
58	                        .find(|p| p.id == release.package)
59	                        .and_then(|p| p.version_grammar().ok())
60	                        .unwrap_or(callisto_model::VersionGrammar::SemVer);
61	                    if let Ok(ver) = callisto_model::Version::parse(v_str, grammar) {
62	                        if let Some(major_tag) = tmpl.render_floating_major(&ver) {
63	                            let major_already_existed = ws.tags()?.contains_tag(major_tag.as_str());
64	                            tags.push(CreatedTag {
65	                                package: release.package.clone(),
66	                                tag_name: major_tag,
67	                                sha: release.sha.clone(),
68	                                already_existed: major_already_existed,
69	                                is_floating_major: true,
70	                            });
71	                        }
72	                    }
73	                }
74	            }
75	
76	            let already_existed = ws.tags()?.contains_tag(tag_str);
77	            let sha = if already_existed {
78	                match git.resolve_commit(tag_str)? {
79	                    Some(actual) => actual,
80	                    None => {
81	                        return Err(GraphError::Vcs(VcsError::RefNotFound {
82	                            ref_name: tag_str.to_string(),
83	                        }))
84	                    }
85	                }
86	            } else {
87	                release.sha.clone()
88	            };
89	
90	            tags.push(CreatedTag {
91	                package: release.package.clone(),
92	                tag_name: release.tag_name.clone(),
93	                sha,
94	                already_existed,
95	                is_floating_major: false,
96	            });
97	            continue;
98	        };
99	
100	        let already_existed = ws.tags()?.contains_tag(tag_str);
101	
102	        let sha = if already_existed {
103	            match git.resolve_commit(tag_str)? {
104	                Some(actual) => actual,
105	                None => {
106	                    return Err(GraphError::Vcs(VcsError::RefNotFound {
107	                        ref_name: tag_str.to_string(),
108	                    }))
109	                }
110	            }
111	        } else {
112	            let msg = format!("Release {}", tag_str);
113	            git.create_tag(tag_str, &release.sha, Some(&msg), permit)?;
114	            release.sha.clone()
115	        };
116	
117	        if opts.floating_major {
118	            let tmpl = ws.tags()?.template(&release.package);
119	            let ver_str = tmpl.extract_version_str(release.tag_name.as_str());
120	            let grammar = ws
121	                .graph
122	                .packages()
123	                .find(|p| p.id == release.package)
124	                .and_then(|p| p.version_grammar().ok())
125	                .unwrap_or(callisto_model::VersionGrammar::SemVer);
126	
127	            if let Some(v_str) = ver_str {
128	                if let Ok(ver) = callisto_model::Version::parse(v_str, grammar) {
129	                    if let Some(major_tag) = tmpl.render_floating_major(&ver) {
130	                        let major_already_existed = ws.tags()?.contains_tag(major_tag.as_str());
131	                        git.create_floating_major(major_tag.as_str(), &release.sha, permit)?;
132	                        tags.push(CreatedTag {
133	                            package: release.package.clone(),
134	                            tag_name: major_tag,
135	                            sha: release.sha.clone(),
136	                            already_existed: major_already_existed,
137	                            is_floating_major: true,
138	                        });
139	                    }
140	                }
141	            }
142	        }
143	
144	        tags.push(CreatedTag {
145	            package: release.package.clone(),
146	            tag_name: release.tag_name.clone(),
147	            sha,
148	            is_floating_major: false,
149	            already_existed,
150	        });
151	    }
152	
153	    Ok(TagReport {
154	        schema_version: SCHEMA_VERSION,
155	        tags,
156	        diagnostics: Vec::new(),
157	    })
158	}

