8	#[derive(Clone, Debug, Default)]
9	pub struct ValidateOptions {
10	    pub staged: bool,
11	    pub since: Option<String>,
12	    pub strict: bool,
13	    pub strict_graph: bool,
14	}
15	
16	pub fn validate<R: CommandRunner, D: DependencyResolver>(
17	    ws: &Workspace<'_, R, D>,
18	    opts: &ValidateOptions,
19	) -> Result<ValidateReport, GraphError> {
20	    let mut diagnostics = Vec::new();
21	    let loaded = crate::load_changesets(&ws.root, &ws.config)?;
22	
23	    let target_changesets: Vec<_> = if opts.staged {
24	        let out = ws.runner.run("git", &["diff", "--cached", "--name-only"], &ws.root)?;
25	        if !out.success() {
26	            return Err(GraphError::Command(callisto_model::CommandError::Io {
27	                program: "git".to_string(),
28	                message: crate::apply::redact_git_stderr(&out.stderr),
29	            }));
30	        }
31	        let files: Vec<String> = out
32	            .stdout_trimmed()
33	            .lines()
34	            .map(|l| l.trim_matches('"').to_string())
35	            .collect();
36	        loaded
37	            .into_iter()
38	            .filter(|cs| files.iter().any(|f| cs.path.ends_with(f)))
39	            .collect()
40	    } else if let Some(ref since) = opts.since {
41	        if since.starts_with('-') {
42	            return Err(GraphError::Command(callisto_model::CommandError::Io {
43	                program: "git".to_string(),
44	                message: "invalid since ref".to_string(),
45	            }));
46	        }
47	        let range = format!("{since}..HEAD");
48	        let out = ws.runner.run("git", &["diff", "--name-only", &range, "--"], &ws.root)?;
49	        if !out.success() {
50	            return Err(GraphError::Command(callisto_model::CommandError::Io {
51	                program: "git".to_string(),
52	                message: crate::apply::redact_git_stderr(&out.stderr),
53	            }));
54	        }
55	        let files: Vec<String> = out
56	            .stdout_trimmed()
57	            .lines()
58	            .map(|l| l.trim_matches('"').to_string())
59	            .collect();
60	        loaded
61	            .into_iter()
62	            .filter(|cs| files.iter().any(|f| cs.path.ends_with(f)))
63	            .collect()
64	    } else {
65	        loaded
66	    };
67	
68	    for cs in &target_changesets {
69	        if cs.changeset.entries.is_empty() {
70	            diagnostics.push(callisto_model::Diagnostic {
71	                code: callisto_model::DiagnosticCode::EmptyChangeset,
72	                severity: callisto_model::DiagnosticSeverity::Error,
73	                message: format!("Changeset `{}` is empty", cs.path.display()),
74	                package: None,
75	                path: Some(cs.path.clone()),
76	                governed_by: None,
77	                escalated_by: None,
78	            });
79	        }
80	
81	        if !cs.changeset.entries.is_empty() && cs.changeset.summary.trim().is_empty() {
82	            diagnostics.push(callisto_model::Diagnostic {
83	                code: callisto_model::DiagnosticCode::EmptySummary,
84	                severity: callisto_model::DiagnosticSeverity::Error,
85	                message: format!("Changeset `{}` has entries but an empty summary", cs.path.display()),
86	                package: None,
87	                path: Some(cs.path.clone()),
88	                governed_by: None,
89	                escalated_by: None,
90	            });
91	        }
92	
93	        for entry in &cs.changeset.entries {
94	            match callisto_model::PackageId::parse(&entry.name) {
95	                Ok(id) => match id.resolve_unique(ws.graph.packages(), |p| &p.id) {
96	                    Ok(None) => {
97	                        diagnostics.push(callisto_model::Diagnostic {
98	                            code: callisto_model::DiagnosticCode::UnknownPackage,
99	                            severity: callisto_model::DiagnosticSeverity::Error,
100	                            message: format!(
101	                                "Changeset `{}` references unknown package `{}`",
102	                                cs.path.display(),
103	                                entry.name
104	                            ),
105	                            package: Some(id),
106	                            path: Some(cs.path.clone()),
107	                            governed_by: None,
108	                            escalated_by: None,
109	                        });
110	                    }
111	                    Ok(Some(_)) => {}
112	                    Err(candidates) => {
113	                        let names: Vec<String> = candidates.iter().map(|p| p.id.display_name().to_string()).collect();
114	                        diagnostics.push(callisto_model::Diagnostic {
115	                            code: callisto_model::DiagnosticCode::AmbiguousPackageName,
116	                            severity: callisto_model::DiagnosticSeverity::Error,
117	                            message: format!(
118	                                "Changeset `{}` references ambiguous package `{}` (matches: {})",
119	                                cs.path.display(),
120	                                entry.name,
121	                                names.join(", ")
122	                            ),
123	                            package: Some(id),
124	                            path: Some(cs.path.clone()),
125	                            governed_by: None,
126	                            escalated_by: None,
127	                        });
128	                    }
129	                },
130	                Err(_) => {
131	                    diagnostics.push(callisto_model::Diagnostic {
132	                        code: callisto_model::DiagnosticCode::InvalidPackageName,
133	                        severity: callisto_model::DiagnosticSeverity::Error,
134	                        message: format!(
135	                            "Changeset `{}` contains invalid package name `{}`",
136	                            cs.path.display(),
137	                            entry.name
138	                        ),
139	                        package: None,
140	                        path: Some(cs.path.clone()),
141	                        governed_by: None,
142	                        escalated_by: None,
143	                    });
144	                }
145	            }
146	        }
147	    }
148	
149	    escalate(&mut diagnostics, opts.strict, opts.strict_graph);
150	
151	    let is_valid = diagnostics
152	        .iter()
153	        .all(|d| d.severity != callisto_model::DiagnosticSeverity::Error);
154	    Ok(ValidateReport {
155	        schema_version: SCHEMA_VERSION,
156	        ok: is_valid,
157	        diagnostics,
158	    })
159	}
