use callisto_model::{CommandRunner, ValidateReport, SCHEMA_VERSION};

use crate::aggregate::LoadedChangeset;
use crate::commands::escalate;
use crate::error::GraphError;
use crate::resolver::DependencyResolver;
use crate::Workspace;

/// Runs a `git diff --name-only`-shaped command and filters `loaded` down to
/// changesets whose path matches one of the changed files. Shared by the
/// `--staged` and `--since` branches of [`validate`], which differ only in
/// the git args they pass.
fn changesets_touched_by<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    args: &[&str],
    loaded: Vec<LoadedChangeset>,
) -> Result<Vec<LoadedChangeset>, GraphError> {
    let out = ws.runner.run("git", args, &ws.root)?;
    if !out.success() {
        return Err(GraphError::Command(callisto_model::CommandError::Io {
            program: "git".to_string(),
            message: out.redacted_stderr(),
        }));
    }
    let files: Vec<String> = out
        .stdout_trimmed()
        .lines()
        .map(|l| l.trim_matches('"').to_string())
        .collect();
    Ok(loaded
        .into_iter()
        .filter(|cs| files.iter().any(|f| cs.path.ends_with(f)))
        .collect())
}

#[derive(Clone, Debug, Default)]
pub struct ValidateOptions {
    pub staged: bool,
    pub since: Option<String>,
    pub strict: bool,
    pub strict_graph: bool,
}

pub fn validate<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    opts: &ValidateOptions,
) -> Result<ValidateReport, GraphError> {
    let mut diagnostics = Vec::new();
    let loaded = crate::load_changesets(&ws.root, &ws.config)?;

    let target_changesets: Vec<_> = if opts.staged {
        changesets_touched_by(ws, &["diff", "--cached", "--name-only"], loaded)?
    } else if let Some(ref since) = opts.since {
        if since.starts_with('-') {
            return Err(GraphError::Command(callisto_model::CommandError::Io {
                program: "git".to_string(),
                message: "invalid since ref".to_string(),
            }));
        }
        let range = format!("{since}..HEAD");
        changesets_touched_by(ws, &["diff", "--name-only", &range, "--"], loaded)?
    } else {
        loaded
    };

    for cs in &target_changesets {
        if cs.changeset.entries.is_empty() {
            diagnostics.push(callisto_model::Diagnostic {
                code: callisto_model::DiagnosticCode::EmptyChangeset,
                severity: callisto_model::DiagnosticSeverity::Error,
                message: format!("Changeset `{}` is empty", cs.path.display()),
                package: None,
                path: Some(cs.path.clone()),
                governed_by: None,
                escalated_by: None,
            });
        }

        if !cs.changeset.entries.is_empty() && cs.changeset.summary.trim().is_empty() {
            diagnostics.push(callisto_model::Diagnostic {
                code: callisto_model::DiagnosticCode::EmptySummary,
                severity: callisto_model::DiagnosticSeverity::Error,
                message: format!("Changeset `{}` has entries but an empty summary", cs.path.display()),
                package: None,
                path: Some(cs.path.clone()),
                governed_by: None,
                escalated_by: None,
            });
        }

        for entry in &cs.changeset.entries {
            match callisto_model::PackageId::parse(&entry.name) {
                Ok(id) => match id.resolve_unique(ws.graph.packages(), |p| &p.id) {
                    Ok(None) => {
                        diagnostics.push(callisto_model::Diagnostic {
                            code: callisto_model::DiagnosticCode::UnknownPackage,
                            severity: callisto_model::DiagnosticSeverity::Error,
                            message: format!(
                                "Changeset `{}` references unknown package `{}`",
                                cs.path.display(),
                                entry.name
                            ),
                            package: Some(id),
                            path: Some(cs.path.clone()),
                            governed_by: None,
                            escalated_by: None,
                        });
                    }
                    Ok(Some(_)) => {}
                    Err(candidates) => {
                        let names: Vec<String> = candidates.iter().map(|p| p.id.display_name().to_string()).collect();
                        diagnostics.push(callisto_model::Diagnostic {
                            code: callisto_model::DiagnosticCode::AmbiguousPackageName,
                            severity: callisto_model::DiagnosticSeverity::Error,
                            message: format!(
                                "Changeset `{}` references ambiguous package `{}` (matches: {})",
                                cs.path.display(),
                                entry.name,
                                names.join(", ")
                            ),
                            package: Some(id),
                            path: Some(cs.path.clone()),
                            governed_by: None,
                            escalated_by: None,
                        });
                    }
                },
                Err(_) => {
                    diagnostics.push(callisto_model::Diagnostic {
                        code: callisto_model::DiagnosticCode::InvalidPackageName,
                        severity: callisto_model::DiagnosticSeverity::Error,
                        message: format!(
                            "Changeset `{}` contains invalid package name `{}`",
                            cs.path.display(),
                            entry.name
                        ),
                        package: None,
                        path: Some(cs.path.clone()),
                        governed_by: None,
                        escalated_by: None,
                    });
                }
            }
        }
    }

    escalate(&mut diagnostics, opts.strict, opts.strict_graph);

    let is_valid = diagnostics
        .iter()
        .all(|d| d.severity != callisto_model::DiagnosticSeverity::Error);
    Ok(ValidateReport {
        schema_version: SCHEMA_VERSION,
        ok: is_valid,
        diagnostics,
    })
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use callisto_model::{CommandError, CommandOutput, CommandRunner};

    use super::*;
    use crate::locate::IgnoreWalkLocator;
    use crate::Workspace;

    /// A `CommandRunner` that fails every call, echoing a stderr containing
    /// an authenticated GitHub remote URL -- the realistic shape a `git
    /// diff --cached` failure could surface in CI (e.g. a shallow clone or a
    /// detached-HEAD checkout with no cached index to diff against).
    struct LeakyGitRunner;

    impl CommandRunner for LeakyGitRunner {
        fn run(&self, _program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
            Ok(CommandOutput {
                exit_code: Some(128),
                stdout: String::new(),
                stderr: "fatal: unable to access 'REDACTED': The requested URL returned error: 403".to_string(),
            })
        }
    }

    /// `validate --staged`'s `git diff --cached` failure must not leak an
    /// authenticated remote URL's credential into the resulting `GraphError`.
    #[test]
    fn staged_diff_failure_redacts_credential_from_error() {
        let dir = tempfile::tempdir().expect("create tempdir");
        let root = dir.path();
        std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = []\nresolver = \"2\"\n").unwrap();
        std::fs::write(root.join("callisto.toml"), "").unwrap();

        let runner = LeakyGitRunner;
        let locator = IgnoreWalkLocator::new(root);
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("empty workspace should load");

        let opts = ValidateOptions {
            staged: true,
            ..Default::default()
        };
        let err = validate(&ws, &opts).expect_err("git diff failure must surface as an Err");

        let rendered = format!("{err}");
        assert!(
            !rendered.contains("REDACTED"),
            "credential must not survive redaction, got: {rendered}"
        );
        assert!(rendered.contains("[REDACTED]"), "got: {rendered}");
    }

    /// A changeset naming a bare package name that resolves to two or more
    /// packages across different ecosystems (e.g. `cargo/foo` and `npm/foo`)
    /// must be reported as `DiagnosticCode::AmbiguousPackageName`, not
    /// silently pass as if the name were valid. `aggregate()`/`plan_version`
    /// hard-error on this exact input (`GraphError::AmbiguousName`) -- validate
    /// must catch it too, since it's the pre-flight check users run before
    /// `version`.
    #[test]
    fn ambiguous_bare_package_name_is_reported_not_silently_passed() {
        let dir = tempfile::tempdir().expect("create tempdir");
        let root = dir.path();

        std::fs::create_dir_all(root.join("crates/foo")).unwrap();
        std::fs::write(
            root.join("crates/foo/Cargo.toml"),
            "[package]\nname = \"foo\"\nversion = \"1.0.0\"\n",
        )
        .unwrap();
        std::fs::create_dir_all(root.join("packages/foo")).unwrap();
        std::fs::write(
            root.join("packages/foo/package.json"),
            r#"{"name":"foo","version":"1.0.0"}"#,
        )
        .unwrap();
        std::fs::write(root.join("callisto.toml"), "").unwrap();

        std::fs::create_dir_all(root.join(".changeset")).unwrap();
        std::fs::write(
            root.join(".changeset/ambiguous.md"),
            "---\n\"foo\": patch\n---\n\nSome change.\n",
        )
        .unwrap();

        let runner = LeakyGitRunner;
        let locator = IgnoreWalkLocator::new(root);
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        let report = validate(&ws, &ValidateOptions::default()).expect("validate must succeed");

        assert!(
            report
                .diagnostics
                .iter()
                .any(|d| d.code == callisto_model::DiagnosticCode::AmbiguousPackageName),
            "expected an AmbiguousPackageName diagnostic, got: {:?}",
            report.diagnostics
        );
        assert!(
            !report.ok,
            "validate report must not be ok when an ambiguous package name is present"
        );
    }
}

use callisto_model::{ApplyPermit, CommandRunner, CreatedTag, PublishPlan, TagReport, SCHEMA_VERSION};
use callisto_vcs::{GitDataSource, TagSignPolicy, VcsError};

use crate::error::GraphError;
use crate::resolver::DependencyResolver;
use crate::Workspace;

#[derive(Clone, Debug, Default)]
pub struct TagOptions {
    pub floating_major: bool,
}

/// Computes the floating-major tag name and existence check for `release`,
/// or `None` if this package's template can't produce one (no version could
/// be extracted/parsed, or the template renders no floating-major form).
/// Shared by both the preview and write branches of
/// [`create_tags_with_options`] so a future change to template rendering or
/// version-grammar resolution can't make the preview disagree with what
/// actually gets tagged.
fn plan_floating_major<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    release: &callisto_model::ReleaseEntry,
) -> Result<Option<(callisto_model::TagName, bool)>, GraphError> {
    let tmpl = ws.tags()?.template(&release.package);
    let Some(v_str) = tmpl.extract_version_str(release.tag_name.as_str()) else {
        return Ok(None);
    };
    let grammar = ws
        .graph
        .packages()
        .find(|p| p.id == release.package)
        .and_then(|p| p.version_grammar().ok())
        .unwrap_or(callisto_model::VersionGrammar::SemVer);
    let Ok(ver) = callisto_model::Version::parse(v_str, grammar) else {
        return Ok(None);
    };
    let Some(major_tag) = tmpl.render_floating_major(&ver) else {
        return Ok(None);
    };
    let already_existed = ws.tags()?.contains_tag(major_tag.as_str());
    Ok(Some((major_tag, already_existed)))
}

pub fn create_tags<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    plan: &PublishPlan,
    permit: Option<&ApplyPermit>,
) -> Result<TagReport, GraphError> {
    create_tags_with_options(ws, plan, &TagOptions::default(), permit)
}

/// Creates one git tag per release in `plan`.
///
/// `permit` is the dry-run gate: `None` reports the tags that *would* be
/// created without touching a single ref, `Some` creates them. It replaces the
/// former `TagOptions::dry_run` bool so that the preview branch and the write
/// branch cannot disagree -- the write calls simply do not typecheck without a
/// permit in hand.
pub fn create_tags_with_options<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    plan: &PublishPlan,
    opts: &TagOptions,
    permit: Option<&ApplyPermit>,
) -> Result<TagReport, GraphError> {
    let mut tags = Vec::new();

    // `Workspace::git_access` never hard-fails on a missing gix discovery:
    // `wasm32` has no gix at all (excluded from that target's dependency
    // set), and even natively a failed discovery just means every op below
    // runs through the `CommandRunner` fallback instead. Its write
    // operations (`create_tag`/`create_floating_major`) additionally
    // guarantee a discovered repo's result is authoritative and never
    // masked by a shell retry -- see `GitAccess`'s doc comment. Sharing the
    // workspace-scoped instance (rather than a fresh `GitAccess::discover`)
    // means this command doesn't pay for a second discovery when `ws.tags()`
    // below also needs one.
    let git = ws.git_access();

    for release in &plan.releases {
        let tag_str = release.tag_name.as_str();

        let Some(permit) = permit else {
            if opts.floating_major {
                if let Some((major_tag, already_existed)) = plan_floating_major(ws, release)? {
                    tags.push(CreatedTag {
                        package: release.package.clone(),
                        tag_name: major_tag,
                        sha: release.sha.clone(),
                        already_existed,
                        is_floating_major: true,
                    });
                }
            }

            let already_existed = ws.tags()?.contains_tag(tag_str);
            let sha = if already_existed {
                match git.resolve_commit(tag_str)? {
                    Some(actual) => actual,
                    None => {
                        return Err(GraphError::Vcs(VcsError::RefNotFound {
                            ref_name: tag_str.to_string(),
                        }))
                    }
                }
            } else {
                release.sha.clone()
            };

            tags.push(CreatedTag {
                package: release.package.clone(),
                tag_name: release.tag_name.clone(),
                sha,
                already_existed,
                is_floating_major: false,
            });
            continue;
        };

        let already_existed = ws.tags()?.contains_tag(tag_str);

        let sha = if already_existed {
            match git.resolve_commit(tag_str)? {
                Some(actual) => actual,
                None => {
                    return Err(GraphError::Vcs(VcsError::RefNotFound {
                        ref_name: tag_str.to_string(),
                    }))
                }
            }
        } else {
            let msg = format!("Release {}", tag_str);
            git.create_tag(
                tag_str,
                &release.sha,
                Some(&msg),
                TagSignPolicy::RespectRepoConfig,
                permit,
            )?;
            release.sha.clone()
        };

        if opts.floating_major {
            if let Some((major_tag, already_existed)) = plan_floating_major(ws, release)? {
                git.create_floating_major(major_tag.as_str(), &release.sha, permit)?;
                tags.push(CreatedTag {
                    package: release.package.clone(),
                    tag_name: major_tag,
                    sha: release.sha.clone(),
                    already_existed,
                    is_floating_major: true,
                });
            }
        }

        tags.push(CreatedTag {
            package: release.package.clone(),
            tag_name: release.tag_name.clone(),
            sha,
            is_floating_major: false,
            already_existed,
        });
    }

    Ok(TagReport {
        schema_version: SCHEMA_VERSION,
        tags,
        diagnostics: Vec::new(),
    })
}

use std::process::ExitCode;

use callisto_graph::commands::StatusOptions;
use callisto_model::{DiagnosticSeverity, StatusReport};

use crate::cli::{GlobalArgs, OutputFormat, StatusArgs};
use crate::error::CliError;
use crate::output::write_json;
use crate::render;
use crate::runner::CliCommandRunner;
use crate::workspace::load_workspace;

/// Compute the --check exit code as a raw `u8` from a status report.
///
/// Returns:
/// - `1` when there are packages with pending changesets (maps to `ExitCode::FAILURE`).
/// - `2` when no changesets are pending (sentinel for CI scripts).
pub(crate) fn check_exit_code_raw(report: &StatusReport) -> u8 {
    if report.has_changesets {
        1
    } else {
        2
    }
}

pub fn handle(args: StatusArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let runner = CliCommandRunner;
    let ws = load_workspace(global, &runner)?;

    let opts = StatusOptions {
        strict: args.strict,
        strict_graph: args.strict_graph,
    };

    let report = callisto_graph::commands::status(&ws, &opts)?;

    match global.format {
        OutputFormat::Json => write_json(&mut std::io::stdout(), &report)?,
        OutputFormat::Text => render::render_status(&report, &mut std::io::stdout())?,
    }

    let has_errors = report
        .diagnostics
        .iter()
        .any(|d| d.severity == DiagnosticSeverity::Error || (args.strict && d.severity == DiagnosticSeverity::Warning));

    if has_errors {
        Ok(ExitCode::FAILURE)
    } else if args.check {
        Ok(ExitCode::from(check_exit_code_raw(&report)))
    } else {
        Ok(ExitCode::SUCCESS)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use callisto_model::{
        Ecosystem, PackageId, ReleaseTrigger, Severity, StatusPackageRecord, Version, VersionGrammar,
    };

    fn v1() -> Version {
        Version::parse("1.0.0", VersionGrammar::SemVer).unwrap()
    }

    fn pkg(name: &str) -> PackageId {
        PackageId::Prefixed {
            ecosystem: Ecosystem::Cargo,
            name: name.to_string(),
        }
    }

    fn make_report(changesets: Vec<Vec<&str>>) -> StatusReport {
        let has_changesets = changesets.iter().any(|cs| !cs.is_empty());
        StatusReport {
            schema_version: callisto_model::SCHEMA_VERSION,
            has_changesets,
            packages: changesets
                .into_iter()
                .enumerate()
                .map(|(i, cs)| StatusPackageRecord {
                    package: pkg(&format!("crate-{i}")),
                    current_version: v1(),
                    last_tag: None,
                    last_released_version: None,
                    pending_severity: if cs.is_empty() { None } else { Some(Severity::Patch) },
                    changed_since_last_tag: !cs.is_empty(),
                    release_trigger: ReleaseTrigger::Changeset,
                    pending_changesets: cs.into_iter().map(|s| s.to_string()).collect(),
                })
                .collect(),
            diagnostics: vec![],
        }
    }

    // QW-3: check=true with pending changesets must return 1 (FAILURE).
    #[test]
    fn check_exit_code_returns_failure_when_changesets_pending() {
        let report = make_report(vec![vec!["cs-001"]]);
        assert_eq!(
            check_exit_code_raw(&report),
            1,
            "check_exit_code must return 1 (FAILURE) when changesets are pending"
        );
    }

    // QW-3: check=true with no pending changesets must return exit code 2.
    #[test]
    fn check_exit_code_returns_2_when_no_changesets_pending() {
        let report = make_report(vec![vec![]]);
        assert_eq!(
            check_exit_code_raw(&report),
            2,
            "check_exit_code must return 2 when no changesets are pending"
        );
    }

    #[test]
    fn handle_text_format_succeeds_on_empty_workspace() {
        let tmp = tempfile::TempDir::new().unwrap();
        let root = tmp.path();
        std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = []\nresolver = \"2\"\n").unwrap();
        std::fs::write(root.join("callisto.toml"), "").unwrap();

        let global = GlobalArgs {
            format: OutputFormat::Text,
            cwd: root.to_path_buf(),
            dry_run: false,
        };

        let result = handle(
            StatusArgs {
                strict: false,
                strict_graph: false,
                check: false,
            },
            &global,
        );
        assert!(result.is_ok(), "expected Ok, got: {result:?}");
        assert_eq!(result.unwrap(), ExitCode::SUCCESS);
    }
}

use std::process::ExitCode;

use crate::cli::{GlobalArgs, OutputFormat, PublishArgs};
use crate::commands::plan_publish::build_plan;
use crate::error::CliError;
use crate::output::write_report_json;
use crate::render;

/// Writes the dry-run text notice for the publish command to the given
/// writer. When the plan contains no publishable packages, emits a clear
/// "nothing to publish (dry run)" message; otherwise previews the plan.
pub(crate) fn write_dry_run_text<W: std::io::Write>(
    plan: &callisto_model::PublishPlan,
    w: &mut W,
) -> std::io::Result<()> {
    let is_empty = plan.rust_crates.is_empty()
        && plan.npm_main_packages.is_empty()
        && plan.npm_platform_packages.is_empty()
        && plan.pypi_packages.is_empty()
        && plan.releases.is_empty();
    if is_empty {
        writeln!(w, "Nothing to publish (dry run).")?;
    } else {
        writeln!(
            w,
            "Dry run: about to publish the following plan (nothing will be published):"
        )?;
        render::render_publish(plan, w)?;
    }
    Ok(())
}

/// Compatibility preview for the retired mutable publish route.
///
/// This command intentionally never obtains an [`callisto_model::ApplyPermit`] or constructs
/// a registry client. Production publication moves to `release execute` once
/// its exact provider adapters are available.
pub fn handle(args: PublishArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let plan = build_plan(global, args.only)?;

    match global.format {
        OutputFormat::Json => write_report_json(&mut std::io::stdout(), &plan)?,
        OutputFormat::Text => {
            write_dry_run_text(&plan, &mut std::io::stdout())?;
            eprintln!("`callisto publish` is a compatibility preview; use `callisto release plan` and `callisto release execute` for durable releases.");
        }
    }
    Ok(ExitCode::SUCCESS)
}

#[cfg(test)]
mod tests {
    use super::*;
    use callisto_model::SCHEMA_VERSION;

    fn empty_plan() -> callisto_model::PublishPlan {
        callisto_model::PublishPlan {
            schema_version: SCHEMA_VERSION,
            rust_crates: vec![],
            npm_main_packages: vec![],
            npm_platform_packages: vec![],
            pypi_packages: vec![],
            releases: vec![],
            diagnostics: vec![],
        }
    }

    #[test]
    fn handle_dry_run_text_format_succeeds_on_empty_workspace() {
        let tmp = tempfile::TempDir::new().unwrap();
        let root = tmp.path();
        std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = []\nresolver = \"2\"\n").unwrap();
        std::fs::write(root.join("callisto.toml"), "").unwrap();

        let global = GlobalArgs {
            format: OutputFormat::Text,
            cwd: root.to_path_buf(),
            dry_run: true,
        };

        let result = handle(PublishArgs::default(), &global);
        assert!(result.is_ok(), "expected Ok, got: {result:?}");
        assert_eq!(result.unwrap(), ExitCode::SUCCESS);
    }

    /// Spec: when no packages would be published and --dry-run is active,
    /// the text output must contain "dry run" (case-insensitive) so the
    /// operator can see that nothing was published.
    #[test]
    fn dry_run_text_contains_dry_run_for_empty_plan() {
        let plan = empty_plan();
        let mut out = Vec::<u8>::new();
        write_dry_run_text(&plan, &mut out).unwrap();
        let text = String::from_utf8(out).unwrap();
        assert!(
            text.to_ascii_lowercase().contains("dry run"),
            "dry-run text output must contain 'dry run', got: {text:?}"
        );
    }

    /// Spec: the empty-plan dry-run message must use present tense ("nothing to
    /// publish") not past tense ("no packages published"), because nothing has
    /// actually happened yet during a dry run. Past-tense wording misleads
    /// operators into thinking the publish already occurred.
    #[test]
    fn dry_run_empty_plan_message_is_present_tense() {
        let plan = empty_plan();
        let mut out = Vec::<u8>::new();
        write_dry_run_text(&plan, &mut out).unwrap();
        let text = String::from_utf8(out).unwrap();
        assert!(
            !text.to_ascii_lowercase().contains("published"),
            "dry-run empty-plan message must NOT use past tense 'published'; got: {text:?}"
        );
        assert!(
            text.to_ascii_lowercase().contains("nothing"),
            "dry-run empty-plan message must say 'nothing'; got: {text:?}"
        );
    }

    /// PUB-010: JSON output for `plan-publish` must include a `"command"`
    /// discriminator field so consumers can distinguish it from `PublishReport`
    /// without inspecting the payload structure.
    #[test]
    fn plan_publish_json_includes_command_discriminator() {
        use crate::output::write_report_json;
        use callisto_model::Report;

        let plan = empty_plan();
        let mut out = Vec::<u8>::new();
        write_report_json(&mut out, &plan).unwrap();
        let text = String::from_utf8(out).unwrap();
        assert!(
            text.contains("\"command\""),
            "plan-publish JSON must contain 'command' field; got: {text}"
        );
        let expected_command = callisto_model::PublishPlan::COMMAND;
        assert!(
            text.contains(&format!("\"{}\"", expected_command)),
            "plan-publish JSON 'command' must be {:?}; got: {text}",
            expected_command
        );
    }

    /// A plan that has pending release entries (e.g. a GitHub release tag) but
    /// no registry packages must NOT print "Nothing to publish" in dry-run
    /// output — the release tag is real pending work that the operator needs
    /// to be aware of before approving the publish.
    #[test]
    fn dry_run_release_only_plan_is_not_empty() {
        use callisto_model::{CommitSha, PackageId, ReleaseEntry, TagName, SCHEMA_VERSION};

        let sha = CommitSha::parse("a".repeat(40).as_str()).unwrap();
        let plan = callisto_model::PublishPlan {
            schema_version: SCHEMA_VERSION,
            rust_crates: vec![],
            npm_main_packages: vec![],
            npm_platform_packages: vec![],
            pypi_packages: vec![],
            releases: vec![ReleaseEntry {
                package: PackageId::Bare("my-lib".to_string()),
                tag_name: TagName::parse("my-lib@1.0.0").unwrap(),
                sha,
                changelog_section: None,
                is_prerelease: false,
            }],
            diagnostics: vec![],
        };

        let mut out = Vec::<u8>::new();
        write_dry_run_text(&plan, &mut out).unwrap();
        let text = String::from_utf8(out).unwrap();
        assert!(
            !text.to_ascii_lowercase().contains("nothing to publish"),
            "dry-run output for a release-only plan must NOT say 'nothing to publish'; \
             the pending release tag must be visible; got: {text:?}"
        );
        assert!(
            text.contains("my-lib@1.0.0"),
            "dry-run output must mention the pending release tag; got: {text:?}"
        );
    }
}

