        "title": "ReleaseOperationId's hand-rolled Ord drops ArtifactSlotId's attestation fields, breaking Ord/Eq consistency required for its own BTreeSet/BTreeMap use",
        "primary_file": "crates/callisto-model/src/release.rs",
        "primary_lines": "721-726,806-854",
