commit 20bac80026fd80293cdcf85626bfce74c8ced227
Author: Gabe Castro <gabe@techworx.dev>
Date:   Wed Sep 9 08:33:13 2026 -0700

    fix(moon): classify native spawn failures by ErrorKind, not message text

    MoonCommandRunner::run's native path stringified a spawn io::Error
    before classifying it as NotFound vs Io, matching "not found"/"no such
    file" substrings in the lowercased Display text. That heuristic is a
    locale/wording-dependent proxy for something the stdlib already
    type-checks: ErrorKind::NotFound. A non-English locale or a future
    libc wording change could silently misclassify an ENOENT-class error
    as CommandError::Io, breaking the "tool isn't installed" UX several
    call sites branch on CommandError::NotFound for.

    Extract classify_native_io_error, mirroring
    CliCommandRunner::run's e.kind() == ErrorKind::NotFound check in
    callisto-cli/src/runner.rs. The string heuristic (classify_host_failure/
    looks_like_not_found) stays in place -- runner_pdk.rs's wasm/pdk path
    still needs it, since warpgate_pdk errors carry no ErrorKind.

    Claude-Session: https://claude.ai/code/REDACTED

diff --git a/crates/callisto-moon/src/runner.rs b/crates/callisto-moon/src/runner.rs
index 3764c708..30e8af78 100644
--- a/crates/callisto-moon/src/runner.rs
+++ b/crates/callisto-moon/src/runner.rs
@@ -29,7 +29,27 @@ impl CommandRunner for MoonCommandRunner {
                 stdout: String::from_utf8_lossy(&output.stdout).to_string(),
                 stderr: String::from_utf8_lossy(&output.stderr).to_string(),
             }),
-            Err(e) => Err(classify_host_failure(program, &e.to_string())),
+            Err(e) => Err(classify_native_io_error(program, &e)),
+        }
+    }
+}
+
+// Native spawn failures carry a real `std::io::Error`, so classification
+// uses `ErrorKind::NotFound` directly (mirroring
+// `callisto_cli::runner::CliCommandRunner::run`) rather than the
+// message-text heuristic below: that heuristic is a fallback for the `pdk`
+// (wasm) path in `runner_pdk.rs`, where host-exec failures carry no
+// `ErrorKind` at all.
+#[cfg(not(feature = "pdk"))]
+fn classify_native_io_error(program: &str, e: &std::io::Error) -> CommandError {
+    if e.kind() == std::io::ErrorKind::NotFound {
+        CommandError::NotFound {
+            program: program.to_string(),
+        }
+    } else {
+        CommandError::Io {
+            program: program.to_string(),
+            message: e.to_string(),
         }
     }
 }
@@ -99,4 +119,47 @@ mod tests {
             .unwrap_err();
         assert!(matches!(err, CommandError::NotFound { .. }));
     }
+
+    /// Proves the native path classifies via `ErrorKind::NotFound` directly
+    /// rather than sniffing the error's `Display` text: a synthetic
+    /// `io::Error` carrying `ErrorKind::NotFound` but a message that does
+    /// NOT contain "not found" or "no such file" (so it would fail the old
+    /// string-heuristic classification) must still classify as
+    /// `CommandError::NotFound`.
+    #[cfg(not(feature = "pdk"))]
+    #[test]
+    fn classify_native_io_error_uses_error_kind_not_message_text() {
+        let e = std::io::Error::new(
+            std::io::ErrorKind::NotFound,
+            "totally unrelated wording, e.g. locale-specific",
+        );
+        let err = classify_native_io_error("ghost-cmd", &e);
+        assert_eq!(
+            err,
+            CommandError::NotFound {
+                program: "ghost-cmd".to_string()
+            }
+        );
+    }
+
+    /// Sibling check: a non-`NotFound` `ErrorKind` whose message happens to
+    /// contain "not found" text must still classify as `Io`, not
+    /// `NotFound` -- proving the native path keys off `ErrorKind`, not the
+    /// message.
+    #[cfg(not(feature = "pdk"))]
+    #[test]
+    fn classify_native_io_error_does_not_misclassify_on_message_text_alone() {
+        let e = std::io::Error::new(
+            std::io::ErrorKind::PermissionDenied,
+            "file not found in a weird phrasing",
+        );
+        let err = classify_native_io_error("git", &e);
+        assert_eq!(
+            err,
+            CommandError::Io {
+                program: "git".to_string(),
+                message: e.to_string(),
+            }
+        );
+    }
 }

