+/// `Ord`, violating the invariant `BTreeSet`/`BTreeMap` require:
+/// `a.cmp(b) == Equal` iff `a == b`.
+fn version_ord_key(v: &Version) -> (VersionGrammar, &str) {
+    (v.grammar(), v.render())
