        diagnostics: vec![],
    };

    let report = render_pr_body_from_plan(&plan, &PrBodyOptions::default()).unwrap();

    assert!(
        report.body.contains(&expected_section),
        "body must contain render_section's verbatim output; body: {}",
        report.body
    );
