/// Classifies `cargo info <pkg>@<version>` output into whether the registry
/// confirms that exact version is published. A non-success exit whose output
/// doesn't match the "not found" shape is ambiguous (could be a transient
/// network or auth failure) and must not be read as "not published" -- it is
/// surfaced as an error instead, exactly like [`classify_cargo_output`].
pub(crate) fn classify_cargo_info_output(output: &CommandOutput) -> Result<bool, RegistryError> {
    if output.success() {
        return Ok(true);
    }
    let combined = combined_lower(output);
    if combined.contains("could not find") {
        return Ok(false);
    }
    Err(RegistryError::Other(format!(
        "cargo info failed (exit {:?}): {}",
        output.exit_code,
        output.redacted_stderr().trim()
    )))
}

