149	/// Strips a URL's userinfo (`user:pass@` between `scheme://` and the
150	/// host) from every `scheme://...` occurrence in `text`, replacing it
151	/// with `[REDACTED]@`. Token-by-token: within the span from `scheme://`
152	/// to the next whitespace/quote/`<`/`>`, everything up to the *last* `@`
153	/// is treated as userinfo.
154	///
155	/// Deliberately conservative, not strictly RFC 3986-aware: userinfo with
156	/// a raw `/` or a second `@` (an unescaped base64-ish token) is realistic
157	/// in free-form CLI stderr, and using the *first* `@` would under-redact
158	/// exactly that case. Cost: a rare false positive (an `@` that's really
159	/// part of a path, e.g. an npm scoped package in
160	/// `registry.npmjs.org/@myorg/pkg`, gets redacted too) -- acceptable,
161	/// since over-redaction only costs log noise while under-redaction leaks
162	/// a credential.
163	fn redact_url_userinfo(text: &str) -> String {
164	    let mut result = String::with_capacity(text.len());
165	    let mut rest = text;
166	    while let Some(scheme_pos) = rest.find("://") {
167	        let split_at = scheme_pos + 3;
168	        result.push_str(&rest[..split_at]);
169	        let after = &rest[split_at..];
170	        let stop = after
171	            .find(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>'))
172	            .unwrap_or(after.len());
173	        let candidate = &after[..stop];
174	        if let Some(at_pos) = candidate.rfind('@') {
175	            result.push_str("[REDACTED]@");
176	            rest = &after[at_pos + 1..];
177	            continue;
178	        }
179	        rest = after;
180	    }
181	    result.push_str(rest);
182	    result
183	}
